class Counter:
    def __init__(self) -> None:
        self._lock = threading.Lock()   # the guardian's own lock
        self._total = 0

    def add(self, delta: int) -> None:
        with self._lock:                # released on every path
            self._total += delta

    def snapshot(self) -> int:
        with self._lock:
            return self._total          # copy out, never the object itself
